import com.comsol.model.*;import com.comsol.model.util.*;import java.io.*;import java.util.*;
public class FluxInterfacePointwise extends ClosureExport{
 static String sd(String sp,int d){if(sp.equals("w4"))return "-("+sd("w1",d)+"+"+sd("w2",d)+"+"+sd("w3",d)+")";return "if(up(dom)=="+d+",-uflux_spatial("+sp+")/tcs.d,-dflux_spatial("+sp+")/tcs.d)";}
 public static void main(String[] a){try{ModelUtil.initStandalone(false);ModelUtil.showProgress(false);ModelUtil.showPlots(false);m=ModelUtil.load("PointwiseInterface",a[0]);data="dset1";sol=1;cid=a[2];m.result().numerical().create("clLine","IntLine");PrintWriter p=new PrintWriter(a[1],"UTF-8");p.println("case,quadrature_order,boundary,species,signed_jump,L1_jump,L1_flux_scale,convective_L1_jump");
 for(int ord:new int[]{4,8}){order=ord;for(int b:new int[]{4,10}){int da=b==4?1:4,db=b==4?2:5;for(String sp:new String[]{"w1","w2","w3","w4"}){String ca=trace("fp.rho*"+sp+"*v",da),cb=trace("-fp.rho*"+sp+"*v",db),fa="("+ca+")+("+sd(sp,da)+")",fb="("+cb+")+("+sd(sp,db)+")",jump="("+fa+")+("+fb+")";p.printf(Locale.US,"%s,%d,%d,%s,%.17g,%.17g,%.17g,%.17g%n",cid,ord,b,sp,integ("IntLine",b,jump),integ("IntLine",b,"abs("+jump+")"),integ("IntLine",b,"abs("+fa+")+abs("+fb+")"),integ("IntLine",b,"abs(("+ca+")+("+cb+"))"));p.flush();}}}p.close();System.out.println("POINTWISE_INTERFACE_EXPORTED|"+cid);System.exit(0);}catch(Throwable e){e.printStackTrace(System.out);System.exit(1);}}
}
